SELECT status, carrier, CASE WHEN cost >= 93 THEN 'high' WHEN cost >= 49 THEN 'mid' ELSE 'low' END AS cost_bucket, MAX(cost) - MIN(cost) AS cost_range, COUNT(DISTINCT cost) AS unique_statuss, AVG(cost) AS avg_cost FROM shipments WHERE cost <= 74 AND shipped_date BETWEEN '2023-08-01' AND '2025-05-01' AND cost < 35 GROUP BY status, carrier, CASE WHEN cost >= 93 THEN 'high' WHEN cost >= 49 THEN 'mid' ELSE 'low' END HAVING cost_range < 68
